static double pv_dot(adcs_vec3_t a,adcs_vec3_t b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static adcs_vec3_t pv_add(adcs_vec3_t a,adcs_vec3_t b){adcs_vec3_t r={a.x+b.x,a.y+b.y,a.z+b.z};return r;}
static double pv_norm(adcs_vec3_t a){return sqrt(pv_dot(a,a));}
adcs_status_t adcs_pilot_davenport_matrix(const adcs_vec3_t *body_vectors,const adcs_vec3_t *inertial_vectors,const double *weights,size_t count,adcs_mat4_t *davenport_k,double *weight_sum);
